-- Objets qui lancent une quête retirée (passe des migrations 100 et 108).
CREATE TABLE solazeroth_v3_t2_sans_quete_objets (entry INT UNSIGNED NOT NULL PRIMARY KEY, startquest INT UNSIGNED NOT NULL, demande TINYINT UNSIGNED NOT NULL) SELECT DISTINCT i.entry, i.startquest, 0 AS demande FROM item_template i JOIN disables d ON d.sourceType = 1 AND d.entry = i.startquest AND d.comment = 'Sol''Azeroth v3 : quete d''origine des Tarides' WHERE i.startquest > 0;
UPDATE solazeroth_v3_t2_sans_quete_objets o SET o.demande = 1 WHERE EXISTS (SELECT 1 FROM quest_template q WHERE o.entry IN (q.RequiredItemId1, q.RequiredItemId2, q.RequiredItemId3, q.RequiredItemId4, q.RequiredItemId5, q.RequiredItemId6, q.ItemDrop1, q.ItemDrop2, q.ItemDrop3, q.ItemDrop4) AND NOT EXISTS (SELECT 1 FROM disables d WHERE d.sourceType = 1 AND d.entry = q.ID));
CREATE TABLE solazeroth_v3_t2_sans_quete_creature SELECT t.* FROM creature_loot_template t JOIN solazeroth_v3_t2_sans_quete_objets o ON o.entry = t.Item AND o.demande = 0 WHERE t.Reference = 0;
DELETE t FROM creature_loot_template t JOIN solazeroth_v3_t2_sans_quete_objets o ON o.entry = t.Item AND o.demande = 0 WHERE t.Reference = 0;
CREATE TABLE solazeroth_v3_t2_sans_quete_gameobject SELECT t.* FROM gameobject_loot_template t JOIN solazeroth_v3_t2_sans_quete_objets o ON o.entry = t.Item AND o.demande = 0 WHERE t.Reference = 0;
DELETE t FROM gameobject_loot_template t JOIN solazeroth_v3_t2_sans_quete_objets o ON o.entry = t.Item AND o.demande = 0 WHERE t.Reference = 0;
CREATE TABLE solazeroth_v3_t2_sans_quete_reference SELECT t.* FROM reference_loot_template t JOIN solazeroth_v3_t2_sans_quete_objets o ON o.entry = t.Item AND o.demande = 0 WHERE t.Reference = 0;
DELETE t FROM reference_loot_template t JOIN solazeroth_v3_t2_sans_quete_objets o ON o.entry = t.Item AND o.demande = 0 WHERE t.Reference = 0;
CREATE TABLE solazeroth_v3_t2_sans_quete_item SELECT t.* FROM item_loot_template t JOIN solazeroth_v3_t2_sans_quete_objets o ON o.entry = t.Item AND o.demande = 0 WHERE t.Reference = 0;
DELETE t FROM item_loot_template t JOIN solazeroth_v3_t2_sans_quete_objets o ON o.entry = t.Item AND o.demande = 0 WHERE t.Reference = 0;
CREATE TABLE solazeroth_v3_t2_sans_quete_pickpocketing SELECT t.* FROM pickpocketing_loot_template t JOIN solazeroth_v3_t2_sans_quete_objets o ON o.entry = t.Item AND o.demande = 0 WHERE t.Reference = 0;
DELETE t FROM pickpocketing_loot_template t JOIN solazeroth_v3_t2_sans_quete_objets o ON o.entry = t.Item AND o.demande = 0 WHERE t.Reference = 0;
CREATE TABLE solazeroth_v3_t2_sans_quete_fishing SELECT t.* FROM fishing_loot_template t JOIN solazeroth_v3_t2_sans_quete_objets o ON o.entry = t.Item AND o.demande = 0 WHERE t.Reference = 0;
DELETE t FROM fishing_loot_template t JOIN solazeroth_v3_t2_sans_quete_objets o ON o.entry = t.Item AND o.demande = 0 WHERE t.Reference = 0;
CREATE TABLE solazeroth_v3_t2_sans_quete_skinning SELECT t.* FROM skinning_loot_template t JOIN solazeroth_v3_t2_sans_quete_objets o ON o.entry = t.Item AND o.demande = 0 WHERE t.Reference = 0;
DELETE t FROM skinning_loot_template t JOIN solazeroth_v3_t2_sans_quete_objets o ON o.entry = t.Item AND o.demande = 0 WHERE t.Reference = 0;
CREATE TABLE solazeroth_v3_t2_sans_quete_marchands SELECT v.* FROM npc_vendor v JOIN solazeroth_v3_t2_sans_quete_objets o ON o.entry = v.item AND o.demande = 0;
DELETE v FROM npc_vendor v JOIN solazeroth_v3_t2_sans_quete_objets o ON o.entry = v.item AND o.demande = 0;
UPDATE item_template i JOIN solazeroth_v3_t2_sans_quete_objets o ON o.entry = i.entry SET i.startquest = 0;

