-- Les quêtes.
INSERT INTO quest_template (ID, QuestType, QuestLevel, MinLevel, QuestSortID, RewardMoney, StartItem, POIContinent, POIx, POIy, LogTitle, LogDescription, QuestDescription, QuestCompletionLog) VALUES (910031, 2, -1, 0, 17, 420, 0, 1, 303, -3686, 'Les Tarides', 'Passe le pont de la Furie-du-Sud et présente-toi à Kargal Balafre-glorieuse, au Poste de garde extérieur.', 'Le Gouffre est purgé, mais une lame brisée se reforge. Ak''Zeloth, mon vieux compagnon de traque, me fait savoir que des survivants ont fui vers l''ouest, au-delà de la Furie-du-Sud. Là-bas commencent les Tarides. Suis la route de l''ouest et passe le pont. Kargal Balafre-glorieuse tient le Poste de garde extérieur, de l''autre côté. Dis-lui que je t''envoie.', 'Retourne voir Kargal Balafre-glorieuse.');
INSERT INTO quest_template_addon (ID, PrevQuestID, ProvidedItemCount) VALUES (910031, 910030, 0);
INSERT INTO quest_request_items (ID, EmoteOnComplete, EmoteOnIncomplete, CompletionText) VALUES (910031, 1, 1, 'Orgnil t''envoie ?');
INSERT INTO quest_offer_reward (ID, Emote1, RewardText) VALUES (910031, 1, 'Orgnil m''a fait prévenir. Ak''Zeloth t''attend aussi, juste à côté. Pose ton sac un instant : les Tarides ne ressemblent pas à Durotar.');
INSERT INTO creature_queststarter (id, quest) VALUES (3142, 910031);
INSERT INTO creature_questender (id, quest) VALUES (3337, 910031);
INSERT INTO quest_poi (QuestID, id, ObjectiveIndex, MapID, WorldMapAreaId, Floor, Priority, Flags) VALUES (910031, 0, -1, 1, 11, 0, 0, 1);
INSERT INTO quest_poi_points (QuestID, Idx1, Idx2, X, Y) VALUES (910031, 0, 0, 303, -3686);
INSERT INTO quest_template (ID, QuestType, QuestLevel, MinLevel, QuestSortID, RewardMoney, StartItem, POIContinent, POIx, POIy, LogTitle, LogDescription, QuestDescription, QuestCompletionLog, RewardItem1, RewardAmount1) VALUES (910041, 2, -1, 0, 17, 420, 0, 1, -473, -2596, 'Au-delà de la Furie-du-Sud', 'Suis la route de l''ouest jusqu''à la Croisée et parle à Thork.', 'Alors c''est toi qui as fait tomber l''Affameur ? Orgnil parle de toi à tous les vents. Bienvenue dans les Tarides. Ici, ce n''est plus Durotar : la savane est grande, les postes sont loin, et personne ne viendra te chercher si tu tombes. Suis la route vers l''ouest. La Croisée est au bout. Thork y commande : il a besoin de bras.', 'Retourne voir Thork.', 37711, 5);
INSERT INTO quest_template_addon (ID, PrevQuestID, ProvidedItemCount) VALUES (910041, 0, 0);
INSERT INTO quest_request_items (ID, EmoteOnComplete, EmoteOnIncomplete, CompletionText) VALUES (910041, 1, 1, 'Thork t''attend à la Croisée.');
INSERT INTO quest_offer_reward (ID, Emote1, RewardText) VALUES (910041, 1, 'Kargal t''envoie ? Bien. Je n''ai pas assez de grunts pour tenir la route, et chaque jour la savane me prend quelque chose. Pose ton sac. Il y a du travail.');
INSERT INTO creature_queststarter (id, quest) VALUES (3337, 910041);
INSERT INTO creature_questender (id, quest) VALUES (3429, 910041);
INSERT INTO quest_poi (QuestID, id, ObjectiveIndex, MapID, WorldMapAreaId, Floor, Priority, Flags) VALUES (910041, 0, -1, 1, 11, 0, 0, 1);
INSERT INTO quest_poi_points (QuestID, Idx1, Idx2, X, Y) VALUES (910041, 0, 0, -473, -2596);
INSERT INTO quest_template (ID, QuestType, QuestLevel, MinLevel, QuestSortID, RewardMoney, StartItem, POIContinent, POIx, POIy, LogTitle, LogDescription, QuestDescription, QuestCompletionLog, RewardItem1, RewardAmount1, RequiredItemId1, RequiredItemCount1) VALUES (910042, 2, -1, 0, 17, 450, 0, 1, -482, -2670, 'La menace des trotteurs', 'Rapporte 7 Becs de trotteur des plaines à Sergra Sombreronce.', 'Les trotteurs des plaines ont toujours été une plaie. Mais cette saison, ils viennent jusqu''aux enclos. Ils arrivent de l''ouest par bandes entières, comme s''ils fuyaient quelque chose. Rapporte-moi sept becs. Ça calmera les autres, et ça me dira s''ils sont malades.', 'Retourne voir Sergra Sombreronce.', 910701, 1, 5087, 7);
INSERT INTO quest_template_addon (ID, PrevQuestID, ProvidedItemCount) VALUES (910042, 910041, 0);
INSERT INTO quest_request_items (ID, EmoteOnComplete, EmoteOnIncomplete, CompletionText) VALUES (910042, 1, 1, 'Sept becs. Les trotteurs ne manquent pas, autour du camp.');
INSERT INTO quest_offer_reward (ID, Emote1, RewardText) VALUES (910042, 1, 'Pas de maladie sur ceux-là. Ils ont peur, voilà tout. Mais peur de quoi ? Prends ces bottes : la savane use le cuir.');
INSERT INTO creature_queststarter (id, quest) VALUES (3338, 910042);
INSERT INTO creature_questender (id, quest) VALUES (3338, 910042);
INSERT INTO quest_poi (QuestID, id, ObjectiveIndex, MapID, WorldMapAreaId, Floor, Priority, Flags) VALUES (910042, 0, 4, 1, 11, 0, 0, 1);
INSERT INTO quest_poi_points (QuestID, Idx1, Idx2, X, Y) VALUES (910042, 0, 0, -33, -2535), (910042, 0, 1, -46, -2503), (910042, 0, 2, -78, -2490), (910042, 0, 3, -110, -2503), (910042, 0, 4, -123, -2535), (910042, 0, 5, -110, -2567), (910042, 0, 6, -78, -2580), (910042, 0, 7, -46, -2567);
INSERT INTO quest_poi (QuestID, id, ObjectiveIndex, MapID, WorldMapAreaId, Floor, Priority, Flags) VALUES (910042, 1, 4, 1, 11, 0, 0, 1);
