INSERT INTO quest_poi_points (QuestID, Idx1, Idx2, X, Y) VALUES (910042, 2, 0, -482, -2670);
INSERT INTO quest_template (ID, QuestType, QuestLevel, MinLevel, QuestSortID, RewardMoney, StartItem, POIContinent, POIx, POIy, LogTitle, LogDescription, QuestDescription, QuestCompletionLog, RewardItem1, RewardAmount1, RequiredItemId1, RequiredItemCount1) VALUES (910043, 2, -1, 0, 17, 450, 0, 1, -482, -2670, 'Les zhévras', 'Rapporte 4 Sabots de zhévra à Sergra Sombreronce.', 'Les zhévras sont les plus rapides de la savane. Rien ne les fait courir, d''habitude. Aujourd''hui, ils galopent vers l''est sans s''arrêter, et ils piétinent tout sur leur passage. Ramène-moi quatre sabots. Je veux savoir sur quel sol ils ont couru.', 'Retourne voir Sergra Sombreronce.', 910702, 1, 5086, 4);
INSERT INTO quest_template_addon (ID, PrevQuestID, ProvidedItemCount) VALUES (910043, 910042, 0);
INSERT INTO quest_request_items (ID, EmoteOnComplete, EmoteOnIncomplete, CompletionText) VALUES (910043, 1, 1, 'Les zhévras sont rapides. Toi aussi, j''espère.');
INSERT INTO quest_offer_reward (ID, Emote1, RewardText) VALUES (910043, 1, 'Regarde ces sabots : de la boue verte, presque noire. Elle ne vient pas de chez nous. Il n''y a qu''un endroit où la terre est aussi mouillée : les oasis de l''ouest. Prends ces gants. Et parle à l''apothicaire Helbrim, il a vu la même chose sur les gazelles.');
INSERT INTO creature_queststarter (id, quest) VALUES (3338, 910043);
INSERT INTO creature_questender (id, quest) VALUES (3338, 910043);
INSERT INTO quest_poi (QuestID, id, ObjectiveIndex, MapID, WorldMapAreaId, Floor, Priority, Flags) VALUES (910043, 0, 4, 1, 11, 0, 0, 1);
INSERT INTO quest_poi_points (QuestID, Idx1, Idx2, X, Y) VALUES (910043, 0, 0, -298, -2583), (910043, 0, 1, -311, -2551), (910043, 0, 2, -343, -2538), (910043, 0, 3, -375, -2551), (910043, 0, 4, -388, -2583), (910043, 0, 5, -375, -2615), (910043, 0, 6, -343, -2628), (910043, 0, 7, -311, -2615);
INSERT INTO quest_poi (QuestID, id, ObjectiveIndex, MapID, WorldMapAreaId, Floor, Priority, Flags) VALUES (910043, 1, -1, 1, 11, 0, 0, 1);
INSERT INTO quest_poi_points (QuestID, Idx1, Idx2, X, Y) VALUES (910043, 1, 0, -482, -2670);
INSERT INTO quest_template (ID, QuestType, QuestLevel, MinLevel, QuestSortID, RewardMoney, StartItem, POIContinent, POIx, POIy, LogTitle, LogDescription, QuestDescription, QuestCompletionLog, RewardItem1, RewardAmount1, RequiredItemId1, RequiredItemCount1) VALUES (910044, 2, -1, 0, 17, 480, 0, 1, -425, -2590, 'Spores fongiques', 'Rapporte 4 Spores fongiques des Bassins oubliés à l''apothicaire Helbrim.', 'Les gazelles meurent. Pas de faim, pas de griffes : elles toussent, elles maigrissent, et elles tombent. On en trouve partout autour de la Croisée. Au nord-ouest, près des Bassins oubliés, poussent des champignons que je ne connais pas. Ils crachent des spores quand on les touche. Rapporte-m''en quatre. Avec des gants, de préférence.', 'Retourne voir Apothicaire Helbrim.', 37711, 5, 5012, 4);
INSERT INTO quest_template_addon (ID, PrevQuestID, ProvidedItemCount) VALUES (910044, 910041, 0);
INSERT INTO quest_request_items (ID, EmoteOnComplete, EmoteOnIncomplete, CompletionText) VALUES (910044, 1, 1, 'Les spores ? Ne les respire pas.');
INSERT INTO quest_offer_reward (ID, Emote1, RewardText) VALUES (910044, 1, 'Ces spores sont vivantes… et elles changent ce qu''elles touchent. Ce n''est pas une maladie. C''est autre chose, qui vient d''en dessous. Garde ces Marques. Je vais étudier ça.');
INSERT INTO creature_queststarter (id, quest) VALUES (3390, 910044);
INSERT INTO creature_questender (id, quest) VALUES (3390, 910044);
INSERT INTO quest_poi (QuestID, id, ObjectiveIndex, MapID, WorldMapAreaId, Floor, Priority, Flags) VALUES (910044, 0, 4, 1, 11, 0, 0, 1);
