INSERT INTO quest_template (ID, QuestType, QuestLevel, MinLevel, QuestSortID, RewardMoney, StartItem, POIContinent, POIx, POIy, LogTitle, LogDescription, QuestDescription, QuestCompletionLog, RewardItem1, RewardAmount1, RequiredNpcOrGo1, RequiredNpcOrGoCount1, RequiredNpcOrGo2, RequiredNpcOrGoCount2, RequiredNpcOrGo3, RequiredNpcOrGoCount3) VALUES (910045, 2, -1, 0, 17, 480, 0, 1, -473, -2596, 'La Colline des épines', 'Tue 8 Sourciers, 8 Tisseuses d''épines et 3 Chasseurs Tranchecrin à la Colline des épines.', 'Tu as connu les Tranchecrins en Durotar. Ici, ils sont chez eux. Ils ont un camp sur la Colline des épines, au nord-est, sur la route du pont, et ils attaquent tout ce qui passe entre la Croisée et le pont. Mes caravanes n''arrivent plus. Va leur rappeler qui tient la route.', 'Retourne voir Thork.', 910703, 1, 3267, 8, 3268, 8, 3265, 3);
INSERT INTO quest_template_addon (ID, PrevQuestID, ProvidedItemCount) VALUES (910045, 910041, 0);
INSERT INTO quest_request_items (ID, EmoteOnComplete, EmoteOnIncomplete, CompletionText) VALUES (910045, 1, 1, 'La route est toujours fermée ?');
INSERT INTO quest_offer_reward (ID, Emote1, RewardText) VALUES (910045, 1, 'Les caravanes vont pouvoir passer. Mais leur chef est encore là-haut, avec ses meilleurs guerriers. Prends ces jambières. Tu vas y retourner.');
INSERT INTO creature_queststarter (id, quest) VALUES (3429, 910045);
INSERT INTO creature_questender (id, quest) VALUES (3429, 910045);
