INSERT INTO quest_template (ID, QuestType, QuestLevel, MinLevel, QuestSortID, RewardMoney, StartItem, POIContinent, POIx, POIy, LogTitle, LogDescription, QuestDescription, QuestCompletionLog, RewardItem1, RewardAmount1, RequiredNpcOrGo1, RequiredNpcOrGoCount1, RequiredNpcOrGo2, RequiredNpcOrGoCount2) VALUES (910046, 2, -1, 0, 17, 480, 0, 1, -473, -2596, 'Les cendres de la Lame', 'Tue 8 Cogneurs et 6 Acolytes de la Lame ardente au Pic de Brume-funeste, puis préviens Thork, à la Croisée.', 'Orgnil et moi traquons la Lame ardente depuis des années. Tu as brisé son repaire de Durotar. Mais quand le Gouffre est tombé, une poignée de fanatiques a fui par la savane. Ils se terrent au Pic de Brume-funeste, au nord de la route. Ce ne sont pas des recrues : ce sont ceux qui ont survécu. Ne monte pas là-haut avant d''avoir fait tes preuves à la Croisée. Et quand ce sera fait, dis-le à Thork : la Croisée doit savoir.', 'Retourne voir Thork.', 910704, 1, 3379, 8, 3380, 6);
INSERT INTO quest_template_addon (ID, PrevQuestID, ProvidedItemCount) VALUES (910046, 0, 0);
INSERT INTO quest_request_items (ID, EmoteOnComplete, EmoteOnIncomplete, CompletionText) VALUES (910046, 1, 1, 'Ak''Zeloth t''a envoyé au Pic ?');
INSERT INTO quest_offer_reward (ID, Emote1, RewardText) VALUES (910046, 1, 'Moins de sectateurs, moins de dangers. Ak''Zeloth m''avait prévenu. Mais tu as vu leurs feux : ils ne prient pas des démons. Ils brûlent des herbes, ils parlent de sommeil et de rêves. Je n''aime pas ça. Prends ces brassards.');
