INSERT INTO quest_template (ID, QuestType, QuestLevel, MinLevel, QuestSortID, RewardMoney, StartItem, POIContinent, POIx, POIy, LogTitle, LogDescription, QuestDescription, QuestCompletionLog, RewardItem1, RewardAmount1, RequiredNpcOrGo1, RequiredNpcOrGoCount1, RequiredNpcOrGo2, RequiredNpcOrGoCount2, RequiredItemId1, RequiredItemCount1) VALUES (910047, 2, -1, 0, 17, 480, 0, 1, -473, -2596, 'L''offensive de la Colline', 'Tue 8 Géomanciennes et 8 Défenseurs Tranchecrin au sommet de la Colline des épines, et rapporte la Défense de Kreenig Grondegroin.', 'Kreenig Grondegroin commande la colline. Ses géomanciennes réveillent les ronces, ses défenseurs gardent le sommet. Tant qu''il vit, les Tranchecrins reviendront. Monte, nettoie, et rapporte-moi sa défense. Ce sera plus dur que la première fois. Ne pars pas les mains vides.', 'Retourne voir Thork.', 910705, 1, 3269, 8, 3266, 8, 5063, 1);
INSERT INTO quest_template_addon (ID, PrevQuestID, ProvidedItemCount) VALUES (910047, 0, 0);
INSERT INTO conditions (SourceTypeOrReferenceId, SourceGroup, SourceEntry, SourceId, ElseGroup, ConditionTypeOrReference, ConditionTarget, ConditionValue1, ConditionValue2, ConditionValue3, NegativeCondition, ErrorType, ErrorTextId, ScriptName, Comment) VALUES (19, 0, 910047, 0, 0, 9, 0, 910045, 0, 0, 0, 0, 0, '', 'Sol''Azeroth v3 : T07 se prend avec T05');
