INSERT INTO quest_request_items (ID, EmoteOnComplete, EmoteOnIncomplete, CompletionText) VALUES (910047, 1, 1, 'Kreenig rugit encore sur sa colline ?');
INSERT INTO quest_offer_reward (ID, Emote1, RewardText) VALUES (910047, 1, 'La défense de Kreenig ! La route est à nous, pour un temps. Prends cette arme, elle vient de mes réserves.');
INSERT INTO creature_queststarter (id, quest) VALUES (3429, 910047);
INSERT INTO creature_questender (id, quest) VALUES (3429, 910047);
