INSERT INTO quest_template (ID, QuestType, QuestLevel, MinLevel, QuestSortID, RewardMoney, StartItem, POIContinent, POIx, POIy, LogTitle, LogDescription, QuestDescription, QuestCompletionLog, RewardItem1, RewardAmount1, RequiredNpcOrGo1, RequiredNpcOrGoCount1) VALUES (910048, 2, -1, 0, 17, 480, 0, 1, -473, -2596, 'Sarilus Souillemporte', 'Abats Sarilus Souillemporte, au sommet du Pic de Brume-funeste, et porte ses lettres à Thork.', 'Les survivants de la Lame ont un chef : Sarilus Souillemporte. Il ne commandait pas en Durotar. Il était déjà ici, et depuis longtemps. Je veux savoir ce qu''il cherche dans les Tarides. Abats-le, fouille ses affaires, et porte ce que tu trouves à Thork : la Croisée doit savoir.', 'Retourne voir Thork.', 910706, 1, 3986, 1);
INSERT INTO quest_template_addon (ID, PrevQuestID, ProvidedItemCount) VALUES (910048, 0, 0);
INSERT INTO conditions (SourceTypeOrReferenceId, SourceGroup, SourceEntry, SourceId, ElseGroup, ConditionTypeOrReference, ConditionTarget, ConditionValue1, ConditionValue2, ConditionValue3, NegativeCondition, ErrorType, ErrorTextId, ScriptName, Comment) VALUES (19, 0, 910048, 0, 0, 9, 0, 910046, 0, 0, 0, 0, 0, '', 'Sol''Azeroth v3 : T08 se prend avec T06');
INSERT INTO conditions (SourceTypeOrReferenceId, SourceGroup, SourceEntry, SourceId, ElseGroup, ConditionTypeOrReference, ConditionTarget, ConditionValue1, ConditionValue2, ConditionValue3, NegativeCondition, ErrorType, ErrorTextId, ScriptName, Comment) VALUES (19, 0, 910048, 0, 1, 28, 0, 910046, 0, 0, 0, 0, 0, '', 'Sol''Azeroth v3 : T08 se prend avec T06');
INSERT INTO conditions (SourceTypeOrReferenceId, SourceGroup, SourceEntry, SourceId, ElseGroup, ConditionTypeOrReference, ConditionTarget, ConditionValue1, ConditionValue2, ConditionValue3, NegativeCondition, ErrorType, ErrorTextId, ScriptName, Comment) VALUES (19, 0, 910048, 0, 2, 8, 0, 910046, 0, 0, 0, 0, 0, '', 'Sol''Azeroth v3 : T08 se prend avec T06');
INSERT INTO quest_request_items (ID, EmoteOnComplete, EmoteOnIncomplete, CompletionText) VALUES (910048, 1, 1, 'Ak''Zeloth m''a fait prévenir. Alors, Sarilus ?');
INSERT INTO quest_offer_reward (ID, Emote1, RewardText) VALUES (910048, 1, 'Montre… Des lettres, et pas pour Orgrimmar. Sarilus écrivait à des « druides au croc de serpent ». Il voulait leur acheter un « rêve qui rend fou », une arme contre Thrall. La Lame est finie, mais ces druides-là ne le sont pas. Tonga doit voir ça. Prends ceci, pour ta main gauche. Et va voir les maîtres de la Croisée : tu es $Gprêt:prête; à apprendre.');
INSERT INTO creature_queststarter (id, quest) VALUES (3521, 910048);
INSERT INTO creature_questender (id, quest) VALUES (3429, 910048);
INSERT INTO quest_poi (QuestID, id, ObjectiveIndex, MapID, WorldMapAreaId, Floor, Priority, Flags) VALUES (910048, 0, 0, 1, 11, 0, 0, 1);
INSERT INTO quest_poi_points (QuestID, Idx1, Idx2, X, Y) VALUES (910048, 0, 0, 364, -2264), (910048, 0, 1, 351, -2232), (910048, 0, 2, 319, -2219), (910048, 0, 3, 287, -2232), (910048, 0, 4, 274, -2264), (910048, 0, 5, 287, -2296), (910048, 0, 6, 319, -2309), (910048, 0, 7, 351, -2296);
INSERT INTO quest_poi (QuestID, id, ObjectiveIndex, MapID, WorldMapAreaId, Floor, Priority, Flags) VALUES (910048, 1, -1, 1, 11, 0, 0, 1);
INSERT INTO quest_poi_points (QuestID, Idx1, Idx2, X, Y) VALUES (910048, 1, 0, -473, -2596);
INSERT INTO quest_template (ID, QuestType, QuestLevel, MinLevel, QuestSortID, RewardMoney, StartItem, POIContinent, POIx, POIy, LogTitle, LogDescription, QuestDescription, QuestCompletionLog, Flags, AreaDescription, RewardItem1, RewardAmount1) VALUES (910049, 2, -1, 0, 17, 480, 0, 1, -545, -2673, 'Les bassins oubliés', 'Va voir les Bassins oubliés, au nord-ouest de la Croisée.', 'Thork m''a montré les lettres. Écoute-moi bien. Les oasis des Tarides ne sont pas nées de la pluie. Un druide, Naralex, s''est endormi sous la savane pour la guérir. Son rêve a fait jaillir l''eau. Mais ses disciples se font appeler les Druides du Croc, maintenant, et l''eau a changé. Va aux Bassins oubliés, au nord. C''était la plus pure de toutes. Dis-moi ce que tu y vois.', 'Retourne voir Tonga Totem-runique.', 4, 'Explorer les Bassins oubliés', 37711, 6);
INSERT INTO quest_template_addon (ID, PrevQuestID, ProvidedItemCount, SpecialFlags) VALUES (910049, 910048, 0, 2);
INSERT INTO quest_request_items (ID, EmoteOnComplete, EmoteOnIncomplete, CompletionText) VALUES (910049, 1, 1, 'Les bassins ?');
INSERT INTO quest_offer_reward (ID, Emote1, RewardText) VALUES (910049, 1, 'À sec… et les Kolkar campent sur la boue ? Alors le rêve se retire de là où il donnait la vie. Il se concentre ailleurs. Prends ces Marques. Nous allons suivre l''eau.');
INSERT INTO creature_queststarter (id, quest) VALUES (3448, 910049);
INSERT INTO creature_questender (id, quest) VALUES (3448, 910049);
INSERT INTO quest_poi (QuestID, id, ObjectiveIndex, MapID, WorldMapAreaId, Floor, Priority, Flags) VALUES (910049, 0, 16, 1, 11, 0, 0, 1);
