INSERT INTO quest_template (ID, QuestType, QuestLevel, MinLevel, QuestSortID, RewardMoney, StartItem, POIContinent, POIx, POIy, LogTitle, LogDescription, QuestDescription, QuestCompletionLog, RewardItem1, RewardAmount1, RequiredNpcOrGo1, RequiredNpcOrGoCount1, ObjectiveText1) VALUES (910050, 2, -1, 0, 17, 570, 5068, 1, -545, -2673, 'L''oasis stagnante', 'Jette les Graines séchées dans la Fissure bouillonnante de l''Oasis stagnante.', 'Au sud-est, l''Oasis stagnante bouillonne. Une fissure s''est ouverte au fond, et l''eau qui en sort pue la mort. Prends ces graines. Elles ont poussé près de la Croisée, dans une terre saine. Jette-les dans la fissure : si le rêve est encore bon, elles germeront. Sinon… nous saurons. Les Kolkar et les hyènes rôdent tout autour.', 'Retourne voir Tonga Totem-runique.', 910707, 1, -3737, 1, 'Graines séchées jetées dans la fissure');
INSERT INTO quest_template_addon (ID, PrevQuestID, ProvidedItemCount) VALUES (910050, 910049, 1);
INSERT INTO quest_request_items (ID, EmoteOnComplete, EmoteOnIncomplete, CompletionText) VALUES (910050, 1, 1, 'Les graines ont-elles germé ?');
INSERT INTO quest_offer_reward (ID, Emote1, RewardText) VALUES (910050, 1, 'Elles ont noirci en touchant l''eau. Le rêve de Naralex est devenu un cauchemar, et ce cauchemar sort de terre par les oasis. Garde cette ceinture.');
INSERT INTO creature_queststarter (id, quest) VALUES (3448, 910050);
INSERT INTO creature_questender (id, quest) VALUES (3448, 910050);
