INSERT INTO quest_poi (QuestID, id, ObjectiveIndex, MapID, WorldMapAreaId, Floor, Priority, Flags) VALUES (910050, 1, -1, 1, 11, 0, 0, 1);
INSERT INTO quest_poi_points (QuestID, Idx1, Idx2, X, Y) VALUES (910050, 1, 0, -545, -2673);
INSERT INTO quest_template (ID, QuestType, QuestLevel, MinLevel, QuestSortID, RewardMoney, StartItem, POIContinent, POIx, POIy, LogTitle, LogDescription, QuestDescription, QuestCompletionLog, RewardItem1, RewardAmount1, RequiredItemId1, RequiredItemCount1) VALUES (910051, 2, -1, 0, 17, 570, 0, 1, -545, -2673, 'Source de vie', 'Rapporte 8 Carapaces de Gueule d''acier altérées à Tonga Totem-runique.', 'Les tortues des oasis, les gueules d''acier, vivent dans cette eau depuis toujours. Si le cauchemar change les bêtes, il a commencé par elles. Rapporte-moi huit carapaces. Commence par l''Oasis luxuriante, au sud-ouest, au pied de la colline creuse. C''est de là que tout vient, j''en ai peur. Mais ne t''approche pas de la chute : une bête y veille, que même les Kolkar évitent.', 'Retourne voir Tonga Totem-runique.', 910708, 1, 5098, 8);
INSERT INTO quest_template_addon (ID, PrevQuestID, ProvidedItemCount) VALUES (910051, 0, 0);
INSERT INTO conditions (SourceTypeOrReferenceId, SourceGroup, SourceEntry, SourceId, ElseGroup, ConditionTypeOrReference, ConditionTarget, ConditionValue1, ConditionValue2, ConditionValue3, NegativeCondition, ErrorType, ErrorTextId, ScriptName, Comment) VALUES (19, 0, 910051, 0, 0, 9, 0, 910050, 0, 0, 0, 0, 0, '', 'Sol''Azeroth v3 : T11 se prend avec T10');
INSERT INTO conditions (SourceTypeOrReferenceId, SourceGroup, SourceEntry, SourceId, ElseGroup, ConditionTypeOrReference, ConditionTarget, ConditionValue1, ConditionValue2, ConditionValue3, NegativeCondition, ErrorType, ErrorTextId, ScriptName, Comment) VALUES (19, 0, 910051, 0, 1, 28, 0, 910050, 0, 0, 0, 0, 0, '', 'Sol''Azeroth v3 : T11 se prend avec T10');
INSERT INTO conditions (SourceTypeOrReferenceId, SourceGroup, SourceEntry, SourceId, ElseGroup, ConditionTypeOrReference, ConditionTarget, ConditionValue1, ConditionValue2, ConditionValue3, NegativeCondition, ErrorType, ErrorTextId, ScriptName, Comment) VALUES (19, 0, 910051, 0, 2, 8, 0, 910050, 0, 0, 0, 0, 0, '', 'Sol''Azeroth v3 : T11 se prend avec T10');
INSERT INTO quest_request_items (ID, EmoteOnComplete, EmoteOnIncomplete, CompletionText) VALUES (910051, 1, 1, 'Les gueules d''acier mordent fort, et ne lâchent pas.');
INSERT INTO quest_offer_reward (ID, Emote1, RewardText) VALUES (910051, 1, 'Regarde ces carapaces : tordues, couvertes d''épines qui n''ont rien à y faire. L''Oasis luxuriante est la source. Sous elle s''ouvrent les Cavernes des Lamentations, où dort Naralex. Prends ce plastron. Je dois parler à Falla.');
INSERT INTO creature_queststarter (id, quest) VALUES (3448, 910051);
INSERT INTO creature_questender (id, quest) VALUES (3448, 910051);
INSERT INTO quest_poi (QuestID, id, ObjectiveIndex, MapID, WorldMapAreaId, Floor, Priority, Flags) VALUES (910051, 0, 4, 1, 11, 0, 0, 1);
INSERT INTO quest_poi_points (QuestID, Idx1, Idx2, X, Y) VALUES (910051, 0, 0, -1025, -2118), (910051, 0, 1, -1038, -2086), (910051, 0, 2, -1070, -2073), (910051, 0, 3, -1102, -2086), (910051, 0, 4, -1115, -2118), (910051, 0, 5, -1102, -2150), (910051, 0, 6, -1070, -2163), (910051, 0, 7, -1038, -2150);
INSERT INTO quest_poi (QuestID, id, ObjectiveIndex, MapID, WorldMapAreaId, Floor, Priority, Flags) VALUES (910051, 1, -1, 1, 11, 0, 0, 1);
INSERT INTO quest_poi_points (QuestID, Idx1, Idx2, X, Y) VALUES (910051, 1, 0, -545, -2673);
INSERT INTO quest_template (ID, QuestType, QuestLevel, MinLevel, QuestSortID, RewardMoney, StartItem, POIContinent, POIx, POIy, LogTitle, LogDescription, QuestDescription, QuestCompletionLog, RewardItem1, RewardAmount1, RequiredItemId1, RequiredItemCount1) VALUES (910052, 2, -1, 0, 17, 570, 0, 1, -307, -1972, 'Les bracelets de centaure', 'Rapporte 12 Bracelets de centaure pris aux Kolkar de l''Oasis luxuriante.', 'Les Kolkar ont toujours pillé. Mais ceux des oasis ont changé : ils boivent cette eau, et ils deviennent fous. Ils se jettent sur nos patrouilles sans crier, les yeux verts. Ils portent des bracelets de cuivre. Rapporte-m''en douze, que les tribus sachent ce qu''il en coûte.', 'Retourne voir Regthar Seuil-de-mort.', 910709, 1, 5030, 12);
INSERT INTO quest_template_addon (ID, PrevQuestID, ProvidedItemCount) VALUES (910052, 910048, 0);
INSERT INTO quest_request_items (ID, EmoteOnComplete, EmoteOnIncomplete, CompletionText) VALUES (910052, 1, 1, 'Les Kolkar sont-ils moins nombreux ?');
INSERT INTO quest_offer_reward (ID, Emote1, RewardText) VALUES (910052, 1, 'Douze. Ça ne les arrêtera pas, mais ça les fera réfléchir. Prends cette cape.');
INSERT INTO creature_queststarter (id, quest) VALUES (3389, 910052);
INSERT INTO creature_questender (id, quest) VALUES (3389, 910052);
