INSERT INTO quest_template (ID, QuestType, QuestLevel, MinLevel, QuestSortID, RewardMoney, StartItem, POIContinent, POIx, POIy, LogTitle, LogDescription, QuestDescription, QuestCompletionLog, RewardItem1, RewardAmount1, RequiredItemId1, RequiredItemCount1) VALUES (910053, 2, -1, 0, 17, 660, 0, 1, -307, -1972, 'Hezrul Marque-de-sang', 'Abats Hezrul Marque-de-sang, à l''Oasis luxuriante, et rapporte sa tête.', 'Hezrul Marque-de-sang mène les Kolkar de l''Oasis luxuriante. Il a bu plus que les autres. On dit qu''il ne dort plus, qu''il parle à l''eau. Abats-le. Sans lui, ses guerriers se disperseront. Mais il est entouré, et la folie le rend dur à tuer.', 'Retourne voir Regthar Seuil-de-mort.', 910710, 1, 5025, 1);
INSERT INTO quest_template_addon (ID, PrevQuestID, ProvidedItemCount) VALUES (910053, 0, 0);
INSERT INTO conditions (SourceTypeOrReferenceId, SourceGroup, SourceEntry, SourceId, ElseGroup, ConditionTypeOrReference, ConditionTarget, ConditionValue1, ConditionValue2, ConditionValue3, NegativeCondition, ErrorType, ErrorTextId, ScriptName, Comment) VALUES (19, 0, 910053, 0, 0, 9, 0, 910052, 0, 0, 0, 0, 0, '', 'Sol''Azeroth v3 : T13 se prend avec T12');
INSERT INTO conditions (SourceTypeOrReferenceId, SourceGroup, SourceEntry, SourceId, ElseGroup, ConditionTypeOrReference, ConditionTarget, ConditionValue1, ConditionValue2, ConditionValue3, NegativeCondition, ErrorType, ErrorTextId, ScriptName, Comment) VALUES (19, 0, 910053, 0, 1, 28, 0, 910052, 0, 0, 0, 0, 0, '', 'Sol''Azeroth v3 : T13 se prend avec T12');
INSERT INTO conditions (SourceTypeOrReferenceId, SourceGroup, SourceEntry, SourceId, ElseGroup, ConditionTypeOrReference, ConditionTarget, ConditionValue1, ConditionValue2, ConditionValue3, NegativeCondition, ErrorType, ErrorTextId, ScriptName, Comment) VALUES (19, 0, 910053, 0, 2, 8, 0, 910052, 0, 0, 0, 0, 0, '', 'Sol''Azeroth v3 : T13 se prend avec T12');
INSERT INTO quest_request_items (ID, EmoteOnComplete, EmoteOnIncomplete, CompletionText) VALUES (910053, 1, 1, 'Hezrul vit encore ?');
INSERT INTO quest_offer_reward (ID, Emote1, RewardText) VALUES (910053, 1, 'La tête d''Hezrul… Ses yeux sont verts, même morts. Ce n''est plus une guerre de centaures. Prends cette arme.');
INSERT INTO creature_queststarter (id, quest) VALUES (3389, 910053);
INSERT INTO creature_questender (id, quest) VALUES (3389, 910053);
