INSERT INTO quest_template (ID, QuestType, QuestLevel, MinLevel, QuestSortID, RewardMoney, StartItem, POIContinent, POIx, POIy, LogTitle, LogDescription, QuestDescription, QuestCompletionLog, RewardItem1, RewardAmount1, RequiredNpcOrGo1, RequiredNpcOrGoCount1, RequiredNpcOrGo2, RequiredNpcOrGoCount2) VALUES (910054, 2, -1, 0, 17, 540, 0, 1, -836, -3729, 'Les flibustiers des mers du Sud', 'Tue 12 Brigands et 6 Canonniers des mers du Sud sur la Côte des marchands.', 'Bienvenue à Cabestan, $Gl''ami:l''amie; ! Ici, on vend tout à tout le monde. Enfin, quand les pirates nous laissent faire. Les flibustiers des mers du Sud ont débarqué au sud, sur la côte, et ils pillent mes cargaisons. Je te paie bien, foi de Gazleu. Fais-les rembarquer.', 'Retourne voir Gazleu.', 37711, 6, 3381, 12, 3382, 6);
INSERT INTO quest_template_addon (ID, PrevQuestID, ProvidedItemCount) VALUES (910054, 910048, 0);
INSERT INTO quest_request_items (ID, EmoteOnComplete, EmoteOnIncomplete, CompletionText) VALUES (910054, 1, 1, 'Mes cargaisons, mes belles cargaisons…');
INSERT INTO quest_offer_reward (ID, Emote1, RewardText) VALUES (910054, 1, 'Ils réfléchiront avant de revenir ! Tiens, des Marques. Et un conseil : le capitaine Brillesoleil, sur le quai, a une vieille dette à régler avec les humains du sud.');
INSERT INTO creature_queststarter (id, quest) VALUES (3391, 910054);
INSERT INTO creature_questender (id, quest) VALUES (3391, 910054);
