INSERT INTO quest_template (ID, QuestType, QuestLevel, MinLevel, QuestSortID, RewardMoney, StartItem, POIContinent, POIx, POIy, LogTitle, LogDescription, QuestDescription, QuestCompletionLog, RewardItem1, RewardAmount1, RequiredNpcOrGo1, RequiredNpcOrGoCount1, RequiredNpcOrGo2, RequiredNpcOrGoCount2, RequiredNpcOrGo3, RequiredNpcOrGoCount3, RequiredItemId1, RequiredItemCount1) VALUES (910055, 2, -1, 0, 17, 660, 0, 1, -1025, -3689, 'La vengeance d''un capitaine', 'Au Fort du Nord, tue le Capitaine Beaumont, le Canonnier Whessan et le Canonnier Smythe, et rapporte 6 Médailles de Theramore.', 'Les canons du Fort du Nord ont coulé mon navire. Mon équipage dort au fond de la baie. Le capitaine Beaumont commande ce fort, et ses deux canonniers ont tiré. Je ne peux pas les atteindre : moi, je suis un marin sans bateau. Toi, tu as des jambes. Rends-moi justice. Rapporte aussi les médailles de leurs soldats : je les jetterai à la mer, là où ils ont jeté mes hommes.', 'Retourne voir Capitaine Thalo''thas Brillesoleil.', 910711, 1, 3393, 1, 3455, 1, 3454, 1, 5078, 6);
INSERT INTO quest_template_addon (ID, PrevQuestID, ProvidedItemCount) VALUES (910055, 910054, 0);
INSERT INTO quest_request_items (ID, EmoteOnComplete, EmoteOnIncomplete, CompletionText) VALUES (910055, 1, 1, 'Beaumont regarde encore la mer de sa tour ?');
INSERT INTO quest_offer_reward (ID, Emote1, RewardText) VALUES (910055, 1, 'C''est fait, alors. Mes hommes dormiront mieux. Prends ces épaulières : elles étaient à mon second, et il aurait aimé qu''elles servent.');
INSERT INTO creature_queststarter (id, quest) VALUES (3339, 910055);
