INSERT INTO quest_template (ID, QuestType, QuestLevel, MinLevel, QuestSortID, RewardMoney, StartItem, POIContinent, POIx, POIy, LogTitle, LogDescription, QuestDescription, QuestCompletionLog, RewardItem1, RewardAmount1) VALUES (910056, 2, -1, 0, 17, 630, 0, 1, -602, -2260, 'La gardienne de la colline', 'Monte voir Falla Vent-de-sagesse, au sommet de la colline des Cavernes.', 'Les bassins se vident, l''oasis stagnante pourrit, les bêtes changent et les Kolkar deviennent fous. Tout mène aux Cavernes des Lamentations. Falla Vent-de-sagesse veille sur la colline depuis le début. Elle a connu Naralex. Monte la voir, et écoute-la.', 'Retourne voir Falla Vent-de-sagesse.', 37711, 6);
INSERT INTO quest_template_addon (ID, PrevQuestID, ProvidedItemCount) VALUES (910056, 0, 0);
INSERT INTO conditions (SourceTypeOrReferenceId, SourceGroup, SourceEntry, SourceId, ElseGroup, ConditionTypeOrReference, ConditionTarget, ConditionValue1, ConditionValue2, ConditionValue3, NegativeCondition, ErrorType, ErrorTextId, ScriptName, Comment) VALUES (19, 0, 910056, 0, 0, 8, 0, 910051, 0, 0, 0, 0, 0, '', 'Sol''Azeroth v3 : T16 demande T11');
INSERT INTO conditions (SourceTypeOrReferenceId, SourceGroup, SourceEntry, SourceId, ElseGroup, ConditionTypeOrReference, ConditionTarget, ConditionValue1, ConditionValue2, ConditionValue3, NegativeCondition, ErrorType, ErrorTextId, ScriptName, Comment) VALUES (19, 0, 910056, 0, 0, 8, 0, 910053, 0, 0, 0, 0, 0, '', 'Sol''Azeroth v3 : T16 demande T13');
INSERT INTO quest_request_items (ID, EmoteOnComplete, EmoteOnIncomplete, CompletionText) VALUES (910056, 1, 1, 'Tonga t''envoie ?');
INSERT INTO quest_offer_reward (ID, Emote1, RewardText) VALUES (910056, 1, 'Naralex dort en bas, et il fait le pire des rêves. Ses disciples l''ont trahi : Cobrahn, Anacondra, Pythas, Serpentis. Ils se nourrissent de son cauchemar et le répandent. Un disciple fidèle attend en bas de pouvoir le réveiller. Mais le cauchemar brise tous ses rituels. Et ses traîtres trouvent de l''aide jusque dans le sud. Va au Camp Taurajo. C''est là-bas que le mal grandit maintenant.');
INSERT INTO creature_queststarter (id, quest) VALUES (3448, 910056);
INSERT INTO creature_questender (id, quest) VALUES (8418, 910056);
INSERT INTO quest_poi (QuestID, id, ObjectiveIndex, MapID, WorldMapAreaId, Floor, Priority, Flags) VALUES (910056, 0, -1, 1, 11, 0, 0, 1);
INSERT INTO quest_poi_points (QuestID, Idx1, Idx2, X, Y) VALUES (910056, 0, 0, -602, -2260);
INSERT INTO quest_template (ID, QuestType, QuestLevel, MinLevel, QuestSortID, RewardMoney, StartItem, POIContinent, POIx, POIy, LogTitle, LogDescription, QuestDescription, QuestCompletionLog, RewardItem1, RewardAmount1) VALUES (910057, 2, -1, 0, 17, 660, 0, 1, -2347, -1925, 'La route de Taurajo', 'Rejoins Kirge Corne-sévère, au Camp Taurajo.', 'Kirge Corne-sévère tient le Camp Taurajo, au sud. Ses éclaireurs ont vu des huréceros Dos-hirsute porter des fioles d''eau verte. Va le voir. Et souviens-toi : le sud n''est pas la Croisée. Ne t''y aventure pas à moitié $Gprêt:prête;.', 'Retourne voir Kirge Corne-sévère.', 910712, 1);
INSERT INTO quest_template_addon (ID, PrevQuestID, ProvidedItemCount) VALUES (910057, 910056, 0);
INSERT INTO quest_request_items (ID, EmoteOnComplete, EmoteOnIncomplete, CompletionText) VALUES (910057, 1, 1, 'Le camp est au bout de la route du sud.');
INSERT INTO quest_offer_reward (ID, Emote1, RewardText) VALUES (910057, 1, 'Falla t''envoie ? Alors tu sais déjà que la savane est malade. Ici, ce sont les Dos-hirsute qui en profitent. Pose-toi, puis va voir Mutiledent. C''est un prisonnier, mais il parle. Prends ces brassards : au sud, la savane mord. Et si tu as du temps, Jorn Oeil-des-cieux cherche un chasseur.');
INSERT INTO creature_queststarter (id, quest) VALUES (8418, 910057);
INSERT INTO creature_questender (id, quest) VALUES (3418, 910057);
INSERT INTO quest_poi (QuestID, id, ObjectiveIndex, MapID, WorldMapAreaId, Floor, Priority, Flags) VALUES (910057, 0, -1, 1, 11, 0, 0, 1);
INSERT INTO quest_poi_points (QuestID, Idx1, Idx2, X, Y) VALUES (910057, 0, 0, -2347, -1925);
INSERT INTO quest_template (ID, QuestType, QuestLevel, MinLevel, QuestSortID, RewardMoney, StartItem, POIContinent, POIx, POIy, LogTitle, LogDescription, QuestDescription, QuestCompletionLog, RewardItem1, RewardAmount1, RequiredNpcOrGo1, RequiredNpcOrGoCount1, RequiredNpcOrGo2, RequiredNpcOrGoCount2, RequiredNpcOrGo3, RequiredNpcOrGoCount3) VALUES (910058, 2, -1, 0, 17, 750, 0, 1, -2392, -1891, 'Tribus en guerre', 'Tue 6 Sourciers, 8 Tisseurs d''épines et 8 Géomanciennes Dos-hirsute à Agama''gor et à Ronceplaie.', 'Mutiledent n''aime pas les Dos-hirsute. Mutiledent était Dos-hirsute. Les géomanciennes ont chassé Mutiledent parce qu''il refusait leur marché. Elles vendent le sang d''Agammagan à des étrangers. Des étrangers qui sentent le serpent. Tue leurs sourciers, leurs tisseurs, leurs géomanciennes. Mutiledent dira la suite.', 'Retourne voir Mutiledent.', 910713, 1, 3260, 6, 3261, 8, 3263, 8);
INSERT INTO quest_template_addon (ID, PrevQuestID, ProvidedItemCount) VALUES (910058, 910057, 0);
INSERT INTO quest_request_items (ID, EmoteOnComplete, EmoteOnIncomplete, CompletionText) VALUES (910058, 1, 1, 'Les épines poussent encore à Agama''gor ?');
INSERT INTO quest_offer_reward (ID, Emote1, RewardText) VALUES (910058, 1, 'Bien, bien. Les géomanciennes ont peur, maintenant. Prends ces jambières. Mutiledent te dira ce qu''elles vendent.');
INSERT INTO creature_queststarter (id, quest) VALUES (3430, 910058);
INSERT INTO creature_questender (id, quest) VALUES (3430, 910058);
