INSERT INTO quest_template (ID, QuestType, QuestLevel, MinLevel, QuestSortID, RewardMoney, StartItem, POIContinent, POIx, POIy, LogTitle, LogDescription, QuestDescription, QuestCompletionLog, RewardItem1, RewardAmount1, RequiredItemId1, RequiredItemCount1) VALUES (910059, 2, -1, 0, 17, 750, 0, 1, -2392, -1891, 'Les joyaux de sang d''Agammagan', 'Rapporte 4 Joyaux de sang d''Agama''gor à Mutiledent.', 'Agammagan est mort il y a longtemps. Là où son sang a coulé, les ronces ont poussé. Les Dos-hirsute en tirent des joyaux rouges, pleins de sa force. Les géomanciennes les vendent aux druides-serpents : avec ce sang, leurs bêtes poussent des épines et ne meurent plus. Rapporte quatre joyaux à Mutiledent. Ils ne les auront pas.', 'Retourne voir Mutiledent.', 910714, 1, 5075, 4);
INSERT INTO quest_template_addon (ID, PrevQuestID, ProvidedItemCount) VALUES (910059, 910058, 0);
INSERT INTO quest_request_items (ID, EmoteOnComplete, EmoteOnIncomplete, CompletionText) VALUES (910059, 1, 1, 'Les joyaux battent comme un cœur. Tu les sentiras.');
INSERT INTO quest_offer_reward (ID, Emote1, RewardText) VALUES (910059, 1, 'Quatre joyaux. Mutiledent les gardera loin des serpents. Prends ceci, pour ta main gauche. Et va voir les maîtres du camp : ils ont des choses à t''apprendre.');
INSERT INTO creature_queststarter (id, quest) VALUES (3430, 910059);
INSERT INTO creature_questender (id, quest) VALUES (3430, 910059);
