INSERT INTO quest_template (ID, QuestType, QuestLevel, MinLevel, QuestSortID, RewardMoney, StartItem, POIContinent, POIx, POIy, LogTitle, LogDescription, QuestDescription, QuestCompletionLog, RewardItem1, RewardAmount1, RequiredNpcOrGo1, RequiredNpcOrGoCount1, ObjectiveText1) VALUES (910060, 2, -1, 0, 17, 750, 0, 1, -521, -2641, 'Portée disparue', 'Retrouve Olgra, la femme de Mankrik, au sud, près de Ronceplaie.', 'Ma femme, Olgra, est partie avec une patrouille vers le sud. La patrouille est revenue. Pas elle. On dit que les Dos-hirsute l''ont prise près des ronces, au sud de la route. Je n''ai pas le cœur d''y aller seul. Trouve-la. Vivante ou non.', 'Retourne voir Mankrik.', 37711, 7, 10668, 1, 'Olgra retrouvée');
INSERT INTO quest_template_addon (ID, PrevQuestID, ProvidedItemCount) VALUES (910060, 910056, 0);
INSERT INTO quest_request_items (ID, EmoteOnComplete, EmoteOnIncomplete, CompletionText) VALUES (910060, 1, 1, 'Tu as des nouvelles d''Olgra ?');
INSERT INTO quest_offer_reward (ID, Emote1, RewardText) VALUES (910060, 1, 'Morte… battue à mort. Merci de me l''avoir dit. Je ne pleurerai pas. Pas encore. Prends ces Marques.');
INSERT INTO creature_queststarter (id, quest) VALUES (3432, 910060);
INSERT INTO creature_questender (id, quest) VALUES (3432, 910060);
INSERT INTO quest_poi (QuestID, id, ObjectiveIndex, MapID, WorldMapAreaId, Floor, Priority, Flags) VALUES (910060, 0, 0, 1, 11, 0, 0, 1);
