INSERT INTO quest_template (ID, QuestType, QuestLevel, MinLevel, QuestSortID, RewardMoney, StartItem, POIContinent, POIx, POIy, LogTitle, LogDescription, QuestDescription, QuestCompletionLog, RewardItem1, RewardAmount1, RequiredItemId1, RequiredItemCount1) VALUES (910061, 2, -1, 0, 17, 750, 0, 1, -521, -2641, 'Consumé par la haine', 'Rapporte 15 Défenses de huran Dos-hirsute à Mankrik.', 'Olgra mérite mieux qu''une tombe sans nom. Les Dos-hirsute l''ont tuée. Je veux leurs défenses, quinze, une pour chaque année passée avec elle. Je n''ai plus de patience, et je n''ai plus de pitié.', 'Retourne voir Mankrik.', 910715, 1, 5085, 15);
INSERT INTO quest_template_addon (ID, PrevQuestID, ProvidedItemCount) VALUES (910061, 0, 0);
INSERT INTO conditions (SourceTypeOrReferenceId, SourceGroup, SourceEntry, SourceId, ElseGroup, ConditionTypeOrReference, ConditionTarget, ConditionValue1, ConditionValue2, ConditionValue3, NegativeCondition, ErrorType, ErrorTextId, ScriptName, Comment) VALUES (19, 0, 910061, 0, 0, 9, 0, 910060, 0, 0, 0, 0, 0, '', 'Sol''Azeroth v3 : T21 se prend avec T20');
INSERT INTO conditions (SourceTypeOrReferenceId, SourceGroup, SourceEntry, SourceId, ElseGroup, ConditionTypeOrReference, ConditionTarget, ConditionValue1, ConditionValue2, ConditionValue3, NegativeCondition, ErrorType, ErrorTextId, ScriptName, Comment) VALUES (19, 0, 910061, 0, 1, 28, 0, 910060, 0, 0, 0, 0, 0, '', 'Sol''Azeroth v3 : T21 se prend avec T20');
INSERT INTO conditions (SourceTypeOrReferenceId, SourceGroup, SourceEntry, SourceId, ElseGroup, ConditionTypeOrReference, ConditionTarget, ConditionValue1, ConditionValue2, ConditionValue3, NegativeCondition, ErrorType, ErrorTextId, ScriptName, Comment) VALUES (19, 0, 910061, 0, 2, 8, 0, 910060, 0, 0, 0, 0, 0, '', 'Sol''Azeroth v3 : T21 se prend avec T20');
INSERT INTO quest_request_items (ID, EmoteOnComplete, EmoteOnIncomplete, CompletionText) VALUES (910061, 1, 1, 'Quinze défenses. Pas une de moins.');
INSERT INTO quest_offer_reward (ID, Emote1, RewardText) VALUES (910061, 1, 'Quinze. Ce n''est pas assez, ça ne le sera jamais. Mais c''est un début. Prends ses gants. Elle aurait voulu qu''ils se battent encore.');
INSERT INTO creature_queststarter (id, quest) VALUES (3432, 910061);
INSERT INTO creature_questender (id, quest) VALUES (3432, 910061);
