INSERT INTO quest_template (ID, QuestType, QuestLevel, MinLevel, QuestSortID, RewardMoney, StartItem, POIContinent, POIx, POIy, LogTitle, LogDescription, QuestDescription, QuestCompletionLog, RewardItem1, RewardAmount1, RequiredItemId1, RequiredItemCount1) VALUES (910062, 2, -1, 0, 17, 810, 0, 1, -2383, -1923, 'Les lézards-tonnerre enragés', 'Rapporte 3 Sangs de lézard-tonnerre à Jorn Oeil-des-cieux.', 'Les lézards-tonnerre sont des bêtes fières, pas des bêtes folles. Depuis la dernière lune, ils chargent nos chasseurs sans raison, et l''un d''eux a renversé un kodo de bât. Apporte-moi trois fioles de leur sang. Si le cauchemar les a touchés, le sang me le dira.', 'Retourne voir Jorn Oeil-des-cieux.', 910716, 1, 5143, 3);
INSERT INTO quest_template_addon (ID, PrevQuestID, ProvidedItemCount) VALUES (910062, 910057, 0);
INSERT INTO quest_request_items (ID, EmoteOnComplete, EmoteOnIncomplete, CompletionText) VALUES (910062, 1, 1, 'Les lézards-tonnerre ne se laissent pas saigner facilement.');
INSERT INTO quest_offer_reward (ID, Emote1, RewardText) VALUES (910062, 1, 'Il y a des épines dans ce sang. Le sang d''Agammagan, mêlé au cauchemar. Les druides-serpents ne se contentent plus des oasis. Prends ces bottes.');
INSERT INTO creature_queststarter (id, quest) VALUES (3387, 910062);
INSERT INTO creature_questender (id, quest) VALUES (3387, 910062);
INSERT INTO quest_poi (QuestID, id, ObjectiveIndex, MapID, WorldMapAreaId, Floor, Priority, Flags) VALUES (910062, 0, 4, 1, 11, 0, 0, 1);
