INSERT INTO quest_template (ID, QuestType, QuestLevel, MinLevel, QuestSortID, RewardMoney, StartItem, POIContinent, POIx, POIy, LogTitle, LogDescription, QuestDescription, QuestCompletionLog, RewardItem1, RewardAmount1, RequiredNpcOrGo1, RequiredNpcOrGoCount1) VALUES (910063, 2, -1, 0, 17, 810, 0, 1, -2347, -1925, 'La géoprêtresse', 'Abats la Géoprêtresse Gukk''rok, au cœur d''Agama''gor.', 'Mutiledent m''a tout dit. Celle qui vend le sang d''Agammagan s''appelle Gukk''rok. C''est la géoprêtresse d''Agama''gor. Elle ne quitte pas le cœur des ronces, et ses gardes ne dorment jamais. Tant qu''elle vit, les druides-serpents auront leur sang. Va, et ne reviens pas avant qu''elle soit tombée.', 'Retourne voir Kirge Corne-sévère.', 910717, 1, 5863, 1);
INSERT INTO quest_template_addon (ID, PrevQuestID, ProvidedItemCount) VALUES (910063, 910059, 0);
INSERT INTO quest_request_items (ID, EmoteOnComplete, EmoteOnIncomplete, CompletionText) VALUES (910063, 1, 1, 'Gukk''rok vit encore ?');
INSERT INTO quest_offer_reward (ID, Emote1, RewardText) VALUES (910063, 1, 'La géoprêtresse est morte. Ses gens racontent qu''avant de tomber, elle a parlé d''un « autre marché », plus au sud, chez les nains. Gann Cime-de-pierre garde la route du sud, et il connaît ces nains mieux que personne. Va le voir. Prends ceci pour te couvrir la tête, c''est un travail d''ici. Tu en auras besoin.');
INSERT INTO creature_queststarter (id, quest) VALUES (3418, 910063);
INSERT INTO creature_questender (id, quest) VALUES (3418, 910063);
