INSERT INTO quest_template (ID, QuestType, QuestLevel, MinLevel, QuestSortID, RewardMoney, StartItem, POIContinent, POIx, POIy, LogTitle, LogDescription, QuestDescription, QuestCompletionLog, RewardItem1, RewardAmount1, RequiredNpcOrGo1, RequiredNpcOrGoCount1, RequiredNpcOrGo2, RequiredNpcOrGoCount2, RequiredItemId1, RequiredItemCount1) VALUES (910064, 2, -1, 0, 17, 810, 0, 1, -3590, -2028, 'La reconquête de Gann', 'À Bael Modan, tue 10 Excavateurs et 5 Contremaîtres de Bael''dun, et rapporte le Journal de Khazgorm.', 'Kirge m''a parlé de toi. Ces terres sont celles de ma famille. Les nains de Bael''dun les éventrent depuis des mois. Ils creusent, ils font sauter la roche, et ils ne disent pas ce qu''ils cherchent. Leur prospecteur, Khazgorm, tient un journal. Je veux savoir ce qu''il y a dedans.', 'Retourne voir Gann Cime-de-pierre.', 910718, 1, 3374, 10, 3375, 5, 5006, 1);
INSERT INTO quest_template_addon (ID, PrevQuestID, ProvidedItemCount) VALUES (910064, 910063, 0);
INSERT INTO quest_request_items (ID, EmoteOnComplete, EmoteOnIncomplete, CompletionText) VALUES (910064, 1, 1, 'Les nains creusent toujours ?');
INSERT INTO quest_offer_reward (ID, Emote1, RewardText) VALUES (910064, 1, 'Lis avec moi… Ils ont trouvé une gemme pâle, qui luit la nuit. Le général Doublenattes l''a enfermée dans son fort, et un « acheteur aux yeux de serpent » la réclame. C''est elle que cherchent les druides-serpents. Prends ce plastron.');
INSERT INTO creature_queststarter (id, quest) VALUES (3341, 910064);
