INSERT INTO quest_template (ID, QuestType, QuestLevel, MinLevel, QuestSortID, RewardMoney, StartItem, POIContinent, POIx, POIy, LogTitle, LogDescription, QuestDescription, QuestCompletionLog, RewardItem1, RewardAmount1, RequiredItemId1, RequiredItemCount1, RequiredItemId2, RequiredItemCount2, RequiredItemId3, RequiredItemCount3) VALUES (910065, 2, -1, 0, 17, 900, 0, 1, -3590, -2028, 'Les explosifs de Gann', 'Rapporte à Gann 4 Nitroglycérine, 4 Pulpe de bois et 4 Nitrate de sodium, pris aux soldats de Bael''dun.', 'Les nains ont une machine volante, à l''ouest de leur fouille. S''ils la font partir, la gemme quittera les Tarides. Je vais la faire sauter avec leurs propres poudres. Leurs soldats en portent sur eux. Rapporte-m''en assez, et je ferai le reste.', 'Retourne voir Gann Cime-de-pierre.', 37711, 8, 5017, 4, 5018, 4, 5019, 4);
INSERT INTO quest_template_addon (ID, PrevQuestID, ProvidedItemCount) VALUES (910065, 0, 0);
