INSERT INTO conditions (SourceTypeOrReferenceId, SourceGroup, SourceEntry, SourceId, ElseGroup, ConditionTypeOrReference, ConditionTarget, ConditionValue1, ConditionValue2, ConditionValue3, NegativeCondition, ErrorType, ErrorTextId, ScriptName, Comment) VALUES (19, 0, 910065, 0, 1, 28, 0, 910064, 0, 0, 0, 0, 0, '', 'Sol''Azeroth v3 : T25 se prend avec T24');
