INSERT INTO quest_request_items (ID, EmoteOnComplete, EmoteOnIncomplete, CompletionText) VALUES (910065, 1, 1, 'La poudre ? Doucement avec la nitroglycérine.');
INSERT INTO quest_offer_reward (ID, Emote1, RewardText) VALUES (910065, 1, 'Voilà de quoi faire un beau feu. Prends ces Marques. Maintenant, il faut le poser.');
