INSERT INTO quest_template (ID, QuestType, QuestLevel, MinLevel, QuestSortID, RewardMoney, StartItem, POIContinent, POIx, POIy, LogTitle, LogDescription, QuestDescription, QuestCompletionLog, RewardItem1, RewardAmount1, RequiredNpcOrGo1, RequiredNpcOrGoCount1, ObjectiveText1) VALUES (910066, 2, -1, 0, 17, 870, 5021, 1, -3590, -2028, 'La machine volante', 'Pose le Bâton explosif de Gann contre la Machine volante de Bael Modan.', 'Prends ce bâton. Pose-le contre la machine, et éloigne-toi vite. Les nains vont accourir. Quand elle aura sauté, Doublenattes n''aura plus de moyen de fuir avec la gemme.', 'Retourne voir Gann Cime-de-pierre.', 910719, 1, -3644, 1, 'Machine volante de Bael Modan détruite');
INSERT INTO quest_template_addon (ID, PrevQuestID, ProvidedItemCount) VALUES (910066, 910065, 1);
INSERT INTO quest_request_items (ID, EmoteOnComplete, EmoteOnIncomplete, CompletionText) VALUES (910066, 1, 1, 'Je n''ai rien entendu sauter.');
INSERT INTO quest_offer_reward (ID, Emote1, RewardText) VALUES (910066, 1, 'Ce bruit ! Toute la savane l''a entendu. Doublenattes est coincé dans son fort, avec la gemme. Un nain rôde autour de la fouille, Feegly. Les siens l''ont chassé, et il jure que la gemme est à lui. Va l''écouter. Prends cette ceinture.');
INSERT INTO creature_queststarter (id, quest) VALUES (3341, 910066);
INSERT INTO creature_questender (id, quest) VALUES (3341, 910066);
INSERT INTO quest_poi (QuestID, id, ObjectiveIndex, MapID, WorldMapAreaId, Floor, Priority, Flags) VALUES (910066, 0, 0, 1, 11, 0, 0, 1);
INSERT INTO quest_poi_points (QuestID, Idx1, Idx2, X, Y) VALUES (910066, 0, 0, -4128, -2137), (910066, 0, 1, -4141, -2105), (910066, 0, 2, -4173, -2092), (910066, 0, 3, -4205, -2105), (910066, 0, 4, -4218, -2137), (910066, 0, 5, -4205, -2169), (910066, 0, 6, -4173, -2182), (910066, 0, 7, -4141, -2169);
INSERT INTO quest_poi (QuestID, id, ObjectiveIndex, MapID, WorldMapAreaId, Floor, Priority, Flags) VALUES (910066, 1, -1, 1, 11, 0, 0, 1);
INSERT INTO quest_poi_points (QuestID, Idx1, Idx2, X, Y) VALUES (910066, 1, 0, -3590, -2028);
INSERT INTO quest_template (ID, QuestType, QuestLevel, MinLevel, QuestSortID, RewardMoney, StartItem, POIContinent, POIx, POIy, LogTitle, LogDescription, QuestDescription, QuestCompletionLog, RewardItem1, RewardAmount1, RequiredNpcOrGo1, RequiredNpcOrGoCount1, RequiredItemId1, RequiredItemCount1) VALUES (910067, 2, -1, 0, 17, 900, 0, 1, -4218, -2342, 'La larme des lunes', 'Abats le Général Doublenattes, en haut du Donjon de Bael''dun, et prends la Larme des lunes dans son coffre.', 'Psst ! Par ici. Tu cherches la gemme, hein ? Tout le monde la cherche. C''est moi qui l''ai trouvée, moi ! Les nains m''ont chassé de la fouille pour la garder. Elle est dans le coffre du général, en haut du fort. Le général ne le quitte pas : il faudra l''abattre. Et un capitaine garde la cour, Gerogg : ne le réveille pas, passe par les remparts. Rapporte-la-moi, et je te dirai qui veut l''acheter. Promis.', 'Retourne voir Feegly l''Exilé.', 910720, 1, 3414, 1, 5038, 1);
INSERT INTO quest_template_addon (ID, PrevQuestID, ProvidedItemCount) VALUES (910067, 910066, 0);
INSERT INTO quest_request_items (ID, EmoteOnComplete, EmoteOnIncomplete, CompletionText) VALUES (910067, 1, 1, 'Le coffre est en haut. Le général aussi, malheureusement.');
INSERT INTO quest_offer_reward (ID, Emote1, RewardText) VALUES (910067, 1, 'La Larme… Elle est froide. Elle me regarde. Non, non, reprends-la. L''acheteur, c''était un druide aux yeux de serpent, avec une voix qui siffle. Il m''a promis de l''or, puis il m''a promis des cauchemars. Je n''en veux plus. Porte-la à qui saura la garder. Et prends ceci, pour ta main gauche. Il était sur le général.');
INSERT INTO creature_queststarter (id, quest) VALUES (3421, 910067);
INSERT INTO creature_questender (id, quest) VALUES (3421, 910067);
