INSERT INTO quest_template (ID, QuestType, QuestLevel, MinLevel, QuestSortID, RewardMoney, StartItem, POIContinent, POIx, POIy, LogTitle, LogDescription, QuestDescription, QuestCompletionLog, RewardItem1, RewardAmount1, RequiredItemId1, RequiredItemCount1, RequiredItemId2, RequiredItemCount2, RequiredItemId3, RequiredItemCount3) VALUES (910068, 2, -1, 0, 17, 900, 0, 1, -2347, -1925, 'Une trahison de l''intérieur', 'Rapporte à Kirge Corne-sévère les crânes de Kuz, de Nak et de Lok Plaie-des-orcs, sur la Crête de Noirépine.', 'Les Tranchecrins de Noirépine se rassemblent sur la Crête de Noirépine, au nord du Kraal. Trois chefs les mènent : Kuz, Nak et Lok Plaie-des-orcs. Ils ont vu les Dos-hirsute s''affaiblir, et ils veulent leurs terres. Puis le camp. Mutiledent connaît leurs huttes. Rapporte leurs crânes à Kirge. Les Tranchecrins sans chefs ne marcheront pas sur Taurajo.', 'Retourne voir Kirge Corne-sévère.', 910721, 1, 5074, 1, 5073, 1, 5072, 1);
INSERT INTO quest_template_addon (ID, PrevQuestID, ProvidedItemCount) VALUES (910068, 910063, 0);
INSERT INTO quest_request_items (ID, EmoteOnComplete, EmoteOnIncomplete, CompletionText) VALUES (910068, 1, 1, 'Les chefs de Noirépine ?');
INSERT INTO quest_offer_reward (ID, Emote1, RewardText) VALUES (910068, 1, 'Trois crânes. Les Tranchecrins vont se terrer dans le Kraal, et nous les y laisserons. J''ai fait garder l''entrée : ce qu''ils ont réveillé en creusant ne nous regarde pas encore. Ni toi ni personne n''y entre. Prends cette arme, tu l''as gagnée.');
