INSERT INTO quest_template (ID, QuestType, QuestLevel, MinLevel, QuestSortID, RewardMoney, StartItem, POIContinent, POIx, POIy, LogTitle, LogDescription, QuestDescription, QuestCompletionLog, RewardItem1, RewardAmount1, RequiredItemId1, RequiredItemCount1) VALUES (910069, 2, -1, 0, 17, 900, 5038, 1, -602, -2260, 'La Larme et le rêve', 'Apporte la Larme des lunes à Falla Vent-de-sagesse, au sommet de la colline des Cavernes.', 'Porte-la aux taurens qui gardent les cavernes, au nord. Très au nord. On dit qu''ils luttent contre ces serpents. Le plus court passe par Taurajo. Moi, je vais me faire oublier. Très oublier.', 'Retourne voir Falla Vent-de-sagesse.', 37711, 8, 5038, 1);
INSERT INTO quest_template_addon (ID, PrevQuestID, ProvidedItemCount) VALUES (910069, 910067, 1);
INSERT INTO quest_request_items (ID, EmoteOnComplete, EmoteOnIncomplete, CompletionText) VALUES (910069, 1, 1, 'Tu portes quelque chose de froid.');
INSERT INTO quest_offer_reward (ID, Emote1, RewardText) VALUES (910069, 1, 'Mu''sha… La Larme des lunes. Elle garde la lumière de la Dame blanche et de l''Enfant bleu. Aucun cauchemar ne l''éteint. Avec elle, le disciple pourra tenir son rituel jusqu''au bout. Les traîtres l''ont cherchée pour la briser : tu la leur as prise. Nous sommes prêts. Presque.');
