INSERT INTO quest_template (ID, QuestType, QuestLevel, MinLevel, QuestSortID, RewardMoney, StartItem, POIContinent, POIx, POIy, LogTitle, LogDescription, QuestDescription, QuestCompletionLog, RewardItem1, RewardAmount1) VALUES (910070, 2, -1, 0, 17, 900, 0, 1, -802, -2039, 'Le seuil des Lamentations', 'Présente-toi à Ebru, dans la grotte des disciples, au-dessus de l''entrée des Cavernes.', 'Ebru garde l''entrée des cavernes avec Nalpak et Kalldan. Va la voir. Mais écoute-moi bien : on ne descend pas là-dessous comme un touriste. Les traîtres sont quatre, leurs bêtes sont pires que tout ce que tu as vu dans la savane, et le cauchemar te parlera. Si les Kolkar, les Dos-hirsute ou les nains te font encore peur, tu n''as rien à faire en bas. Nettoie les Tarides d''abord. Et passe voir l''apothicaire Helbrim, à la Croisée : il cherche une fleur qui ne pousse qu''en bas.', 'Retourne voir Ebru.', 37711, 8);
INSERT INTO quest_template_addon (ID, PrevQuestID, ProvidedItemCount) VALUES (910070, 0, 0);
INSERT INTO conditions (SourceTypeOrReferenceId, SourceGroup, SourceEntry, SourceId, ElseGroup, ConditionTypeOrReference, ConditionTarget, ConditionValue1, ConditionValue2, ConditionValue3, NegativeCondition, ErrorType, ErrorTextId, ScriptName, Comment) VALUES (19, 0, 910070, 0, 0, 8, 0, 910068, 0, 0, 0, 0, 0, '', 'Sol''Azeroth v3 : T30 demande T28');
INSERT INTO conditions (SourceTypeOrReferenceId, SourceGroup, SourceEntry, SourceId, ElseGroup, ConditionTypeOrReference, ConditionTarget, ConditionValue1, ConditionValue2, ConditionValue3, NegativeCondition, ErrorType, ErrorTextId, ScriptName, Comment) VALUES (19, 0, 910070, 0, 0, 8, 0, 910069, 0, 0, 0, 0, 0, '', 'Sol''Azeroth v3 : T30 demande T29');
INSERT INTO quest_request_items (ID, EmoteOnComplete, EmoteOnIncomplete, CompletionText) VALUES (910070, 1, 1, 'Les cavernes t''attendent. Toi, es-tu $Gprêt:prête; ?');
INSERT INTO quest_offer_reward (ID, Emote1, RewardText) VALUES (910070, 1, 'Falla t''envoie, avec la Larme ? Alors tu sais ce qui t''attend. Personne ne descend sans avoir prouvé qu''il connaît la savane. Quand les Tarides parleront de toi, je te laisserai passer. Pas avant.');
