-- Sarilus (faction de la Lame ardente), Takar (dans le Camp Taurajo, faction d'Orgrimmar), Gukk'rok (5 min).
CREATE TABLE solazeroth_v3_t2_pnj_origine SELECT entry, faction FROM creature_template WHERE entry IN (3986, 6244);
CREATE TABLE solazeroth_v3_t2_apparitions_origine SELECT guid, position_x, position_y, position_z, orientation, spawntimesecs FROM creature WHERE guid IN (14333, 20939);
UPDATE creature_template SET faction = 554 WHERE entry = 3986;
UPDATE creature_template SET faction = 29 WHERE entry = 6244;
UPDATE creature SET position_x = -2400.5, position_y = -1924.5, position_z = 96.8255, orientation = 0.56, areaId = 378, wander_distance = 0, MovementType = 0 WHERE guid = 14333;
