-- Cris des chefs (v3_paroles.cpp lit cette table au démarrage).
CREATE TABLE solazeroth_v3_cris (creature INT UNSIGNED NOT NULL PRIMARY KEY, zone INT UNSIGNED NOT NULL, texte VARCHAR(255) NOT NULL) DEFAULT CHARSET=utf8mb4;
INSERT INTO solazeroth_v3_cris VALUES (3183, 14, 'Les recrues de Thrall… La Lame ardente a faim de chair fraîche !'), (3192, 14, 'Un orc dans mon donjon ? Gardes ! Abattez-le !'), (5808, 14, 'La combe est aux Kolkar ! Tu n''en sortiras pas vivant.'), (3205, 14, 'Mes enfants, à moi ! Vol''jin paiera pour cette insolence !'), (3203, 14, 'Tu tombes mal : je préparais justement un petit feu…'), (3204, 14, 'L''Œil m''a montré ta venue. Il m''a aussi montré ta mort.'), (11517, 2437, 'Intrus ! Les Ragefeu vont t''écraser !'), (11518, 2437, 'Les ombres répondent à mon appel, pas au tien !'), (11519, 2437, 'Tu oses descendre dans l''antre de la Lame ?'), (11520, 2437, 'Encore un cœur à dévorer ! Approche !'), (3438, 17, 'La colline est aux Tranchecrins ! Tes os nourriront les ronces.'), (3986, 17, 'Encore un chien de Thrall ? Le rêve te rendra fou, comme les autres.'), (3396, 17, 'L''eau m''a parlé de toi. Elle veut ton sang !'), (3393, 17, 'La Horde dans mon fort ? Canonniers, feu à volonté !'), (5863, 17, 'Le sang d''Agammagan ne sera jamais à toi !'), (3414, 17, 'La gemme appartient à Bael''dun ! Tu n''y toucheras pas !'), (3435, 17, 'Lok écrase les orcs, et tous ceux qui marchent avec eux !');

-- Faux indicateurs de quête de la zone 17 (passe de la migration 120).
CREATE TABLE solazeroth_v3_t2_faux_indicateurs (entry INT UNSIGNED NOT NULL PRIMARY KEY) SELECT DISTINCT t.entry FROM creature c JOIN creature_template t ON t.entry = c.id WHERE c.map = 1 AND c.zoneId = 17 AND (t.npcflag & 2) AND NOT EXISTS (SELECT 1 FROM creature_queststarter q WHERE q.id = t.entry AND NOT EXISTS (SELECT 1 FROM disables d WHERE d.sourceType = 1 AND d.entry = q.quest)) AND NOT EXISTS (SELECT 1 FROM creature_questender q WHERE q.id = t.entry AND NOT EXISTS (SELECT 1 FROM disables d WHERE d.sourceType = 1 AND d.entry = q.quest));
UPDATE creature_template t JOIN solazeroth_v3_t2_faux_indicateurs f ON f.entry = t.entry SET t.npcflag = t.npcflag & ~2;
